function allowedSections(){
  if(role==='admin')return allSections;
  if(role==='patient')return ['dashboard','account','appointments','patientRecord'];
  const granted=Array.isArray(accountAccess?.sections)&&accountAccess.sections.length?accountAccess.sections:(role==='doctor'?permissionTemplates['الدكتور']:permissionTemplates['الاستقبال']);
  const normalized=new Set(granted.filter(x=>allSections.includes(x)));
  if(granted.some(x=>['patients','sessions','odontogram','plans','prescriptions','imaging','finance'].includes(x)))normalized.add('patients');
  normalized.add('dashboard');
  return allSections.filter(x=>normalized.has(x));
}
