const patientById=id=>db.patients.find(p=>p.id===id),currentPatient=()=>patientById(selectedPatientId)||db.patients[0],patientRows=k=>(db[k]||[]).filter(r=>r.patientId===currentPatient()?.id||(!r.patientId&&r.patient===currentPatient()?.name));
function normalizeRecord(k,data,old={}){if(data.patientId){const p=patientById(data.patientId);data.patient=p?.name||old.patient||'';if(k==='finance'&&!data.person)data.person=data.patient}if(k==='sessions'&&!data.number)data.number=String(db.sessions.filter(s=>s.patientId===data.patientId).length+1);return data}
