const approvedFinance=rows=>(rows||db.finance).filter(x=>x.status==='معتمدة');
function financeTotals(rows=db.finance){const approved=approvedFinance(rows),sum=type=>approved.filter(x=>x.type===type).reduce((total,x)=>total+(+x.amount||0),0);const invoices=sum('فاتورة علاج'),payments=sum('دفعة'),refunds=sum('استرداد'),expenses=sum('مصروف');return{invoices,payments,refunds,expenses,paid:Math.max(0,payments-refunds),due:Math.max(0,invoices-payments+refunds),net:payments-refunds-expenses}}
function patientMoney(patientId=currentPatient()?.id){
  const sessions=db.sessions.filter(x=>x.patientId===patientId&&x.status!=='ملغاة');
  const sessionCost=sessions.reduce((n,x)=>n+(+x.amount||0),0),sessionPaid=sessions.reduce((n,x)=>n+Math.min(+x.paidAmount||0,+x.amount||0),0);
  const legacy=financeTotals(db.finance.filter(x=>x.patientId===patientId));
  return{cost:sessionCost+legacy.invoices,paid:sessionPaid+legacy.paid,due:Math.max(0,sessionCost+legacy.invoices-sessionPaid-legacy.paid),sessions};
}
